import networkx as nx
import numpy as np

def select_next_node(graph: nx.Graph, unvisited_nodes: list):
    if not unvisited_nodes:
        return None

    precomputed = graph.graph.get('precomputed', {})
    avg_degree = precomputed.get('avg_degree', 1)
    degree_variance = precomputed.get('degree_variance', 1)
    bridge_ratio = precomputed.get('bridge_ratio_high_bc', 0)

    # Estimate density from avg_degree and number of nodes
    n = graph.number_of_nodes()
    if n > 1:
        density = avg_degree / (n - 1)
    else:
        density = 0.0

    # Adaptive weight settings based on density and bridge ratio
    if density < 0.05:
        w_degree = 0.30
        w_core = 0.15
        w_eigen = 0.20
        w_betweenness = 0.25
        w_cluster = 0.10
    elif density < 0.15:
        w_degree = 0.20
        w_core = 0.22
        w_eigen = 0.30
        w_betweenness = 0.20
        w_cluster = 0.08
    else:
        w_degree = 0.15
        w_core = 0.35
        w_eigen = 0.32
        w_betweenness = 0.12
        w_cluster = 0.06

    # Adjust for high bridge ratio: boost betweenness
    if bridge_ratio > 0.3:
        w_betweenness = min(w_betweenness + 0.10, 0.40)
        total = w_degree + w_core + w_eigen + w_betweenness + w_cluster
        w_degree /= total
        w_core /= total
        w_eigen /= total
        w_betweenness /= total
        w_cluster /= total

    # Gather raw values for normalization
    unvisited_set = set(unvisited_nodes)

    degrees = {node: graph.nodes[node].get('degree', 0) for node in unvisited_nodes}
    cores = {node: graph.nodes[node].get('core_number', 0) for node in unvisited_nodes}
    eigens = {node: graph.nodes[node].get('eigenvector', 0) for node in unvisited_nodes}
    betweens = {node: graph.nodes[node].get('betweenness', 0) for node in unvisited_nodes}
    clusterings = {node: graph.nodes[node].get('clustering', 0) for node in unvisited_nodes}

    def safe_norm(d):
        max_val = max(d.values()) if d else 1
        if max_val == 0:
            max_val = 1
        return {k: v / max_val for k, v in d.items()}

    deg_norm = safe_norm(degrees)
    core_norm = safe_norm(cores)
    eigen_norm = safe_norm(eigens)
    between_norm = safe_norm(betweens)
    cluster_norm = safe_norm(clusterings)

    # Compute coverage count: how many neighbors of each unvisited node are already visited
    visited = set(graph.nodes()) - unvisited_set
    coverage_count = {node: 0 for node in unvisited_nodes}
    for node in unvisited_nodes:
        for nb in graph.neighbors(node):
            if nb in visited:
                coverage_count[node] += 1
            else:
                # slight penalty for 2-hop visited
                for nb2 in graph.neighbors(nb):
                    if nb2 in visited:
                        coverage_count[node] += 0.2

    max_coverage = max(coverage_count.values()) if coverage_count else 1
    if max_coverage == 0:
        max_coverage = 1
    coverage_norm = {node: coverage_count[node] / max_coverage for node in unvisited_nodes}

    penalty_factor = 0.18

    best_node = None
    best_score = -1e18

    for node in unvisited_nodes:
        base_score = (w_degree * deg_norm[node] +
                      w_core * core_norm[node] +
                      w_eigen * eigen_norm[node] +
                      w_betweenness * between_norm[node] +
                      w_cluster * cluster_norm[node])
        effective_score = base_score * (1 - penalty_factor * coverage_norm[node])
        if effective_score > best_score:
            best_score = effective_score
            best_node = node

    return best_node
